import Foundation
import CoreGraphics
import ImageIO
import UniformTypeIdentifiers
import PhotoBursts
import PhotoViewerCore

// Headless acceptance for burst grouping and the keep actions. Shared by
// `pv-pipeline` and the XCTest target. Photos are generated by
// `BurstFixtures`; nothing here touches the user's folders or preferences.

private struct VerificationFailure: Error, CustomStringConvertible {
    let description: String
}

private func check(_ condition: Bool, _ message: @autoclosure () -> String) throws {
    if !condition { throw VerificationFailure(description: message()) }
}

private func scratchFolder() throws -> URL {
    let url = URL(fileURLWithPath: NSTemporaryDirectory())
        .appendingPathComponent("latent-bursts-\(UUID().uuidString)", isDirectory: true)
    try FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
    return url
}

/// Write one generated photo and read its signature back the way the app does.
private func photo(
    _ folder: URL, _ name: String, scene: Int, at time: Double,
    jitter: Int = 0, softness: Double = 0
) throws -> BurstGrouper.Item {
    let url = folder.appendingPathComponent(name)
    try BurstFixtures.writeJPEG(
        BurstFixtures.render(scene: scene, jitter: jitter, softness: softness),
        to: url, capture: time
    )
    guard let signature = BurstSignatureExtractor.signature(for: url) else {
        throw VerificationFailure(description: "\(name): no signature")
    }
    return .init(url: url, signature: signature)
}

/// Frames a second apart that look alike form one group; a look-alike an hour
/// later, a look-alike outside the time gap, unrelated scenes and a lone
/// photo do not; capture time comes from EXIF with sub-seconds; animated
/// images are never analysed.
public func verifyBurstGrouping() async throws {
    let folder = try scratchFolder()
    defer { try? FileManager.default.removeItem(at: folder) }
    let t = 1_700_000_000.0
    let burst = [
        try photo(folder, "a1.jpg", scene: 1, at: t),
        try photo(folder, "a2.jpg", scene: 1, at: t + 1, jitter: 2),
        // Out of focus and nudged at once: the hardest frame that still
        // belongs, 0.32 from its neighbour in Vision's feature print.
        try photo(folder, "a2b.jpg", scene: 1, at: t + 1.5, jitter: 4, softness: 0.35),
        try photo(folder, "a3.jpg", scene: 1, at: t + 2, jitter: 4),
    ]
    let hourLater = try photo(folder, "a-late.jpg", scene: 1, at: t + 3600, jitter: 3)
    let tooFar = try photo(folder, "a-far.jpg", scene: 1, at: t + 2 + 30, jitter: 1)
    let others = [
        try photo(folder, "b.jpg", scene: 2, at: t - 1),
        try photo(folder, "c.jpg", scene: 3, at: t + 500),
        try photo(folder, "d.jpg", scene: 4, at: t + 501),
    ]
    let items = burst + [hourLater, tooFar] + others
    let groups = BurstGrouper.groups(for: items.shuffled())
    try check(groups.count == 1, "expected one group, found \(groups.count)")
    try check(
        groups[0].members == burst.map(\.url),
        "group members \(groups[0].members.map(\.lastPathComponent))"
    )

    // Sub-second capture times survive the EXIF round trip.
    let spread = burst[1].signature.captureTime - burst[0].signature.captureTime
    try check(abs(spread - 1) < 0.02, "capture spacing \(spread)")
    let precise = try photo(folder, "p.jpg", scene: 5, at: t + 0.37)
    try check(abs(precise.signature.captureTime - (t + 0.37)) < 0.011, "sub-second time lost")

    // GIFs and other animated files are never analysed.
    let gif = folder.appendingPathComponent("anim.gif")
    let frame = BurstFixtures.render(scene: 1)
    let dest = CGImageDestinationCreateWithURL(gif as CFURL, UTType.gif.identifier as CFString, 2, nil)!
    CGImageDestinationAddImage(dest, frame, nil)
    CGImageDestinationAddImage(dest, frame, nil)
    try check(CGImageDestinationFinalize(dest), "could not write the GIF")
    try check(BurstSignatureExtractor.signature(for: gif) == nil, "an animated GIF got a signature")
}

/// A partly defocused copy ranks below its sharp original whichever came
/// first, and the reason shown is "Sharpest".
public func verifyBurstRanksSharpest() async throws {
    let folder = try scratchFolder()
    defer { try? FileManager.default.removeItem(at: folder) }
    let t = 1_700_000_000.0
    for blurredFirst in [true, false] {
        let soft = try photo(folder, "soft-\(blurredFirst).jpg", scene: 1, at: t + (blurredFirst ? 0 : 0.5), softness: 0.35)
        let sharp = try photo(folder, "sharp-\(blurredFirst).jpg", scene: 1, at: t + (blurredFirst ? 0.5 : 0))
        try check(
            soft.signature.sharpness < sharp.signature.sharpness * 0.9,
            "sharpness \(soft.signature.sharpness) vs \(sharp.signature.sharpness)"
        )
        let groups = BurstGrouper.groups(for: [soft, sharp])
        try check(groups.count == 1, "the soft copy did not join its original")
        try check(groups[0].best == sharp.url, "suggested \(groups[0].best.lastPathComponent)")
        try check(groups[0].reason == .sharpest, "reason \(groups[0].reason)")
    }
}

/// Face evidence outranks sharpness, which outranks being earlier; reasons
/// say which applied.
public func verifyBurstReasonOrdering() async throws {
    func item(_ name: String, time: Double, sharp: Double, faces: FaceSummary? = nil) -> BurstGrouper.Item {
        .init(
            url: URL(fileURLWithPath: "/burst/\(name).jpg"),
            signature: PhotoSignature(captureTime: time, featurePrint: [1, 0, 0], sharpness: sharp, faces: faces)
        )
    }
    func best(_ items: [BurstGrouper.Item]) -> (String, BurstReason) {
        let (winner, reason) = BurstGrouper.pickBest(items)
        return (winner.url.deletingPathExtension().lastPathComponent, reason)
    }
    let open = FaceSummary(count: 1, quality: 0.6, eyesOpen: true)
    let closed = FaceSummary(count: 1, quality: 0.9, eyesOpen: false)

    // No faces: sharpest wins; equal sharpness keeps the earlier frame.
    try check(best([item("a", time: 0, sharp: 10), item("b", time: 1, sharp: 50), item("c", time: 2, sharp: 30)]) == ("b", .sharpest), "sharpest")
    try check(best([item("a", time: 0, sharp: 10), item("b", time: 1, sharp: 10)]) == ("a", .sharpest), "tie keeps the earlier frame")
    // Open eyes beat a sharper frame with closed eyes, and a better face
    // quality beats sharpness; the reason is the faces.
    try check(best([item("a", time: 0, sharp: 90, faces: closed), item("b", time: 1, sharp: 20, faces: open)]) == ("b", .bestFaces), "eyes open")
    let good = FaceSummary(count: 1, quality: 0.8, eyesOpen: true)
    try check(best([item("a", time: 0, sharp: 90, faces: open), item("b", time: 1, sharp: 20, faces: good)]) == ("b", .bestFaces), "face quality")
    // Quality within tolerance falls through to sharpness.
    let near = FaceSummary(count: 1, quality: 0.61, eyesOpen: true)
    try check(best([item("a", time: 0, sharp: 20, faces: open), item("b", time: 1, sharp: 90, faces: near)]) == ("b", .bestFaces), "tolerance")
    // A frame where the face was lost loses to one that has it.
    try check(best([item("a", time: 0, sharp: 99), item("b", time: 1, sharp: 5, faces: open)]) == ("b", .bestFaces), "lost face")
}

/// The thresholds: gap and distance limits are inclusive, and the anchor
/// limit stops a slow drift from chaining unrelated frames together.
public func verifyBurstThresholds() async throws {
    let s = BurstSettings.standard
    func item(_ name: String, time: Double, at x: Float) -> BurstGrouper.Item {
        .init(
            url: URL(fileURLWithPath: "/burst/\(name).jpg"),
            signature: PhotoSignature(captureTime: time, featurePrint: [x, 0], sharpness: 1)
        )
    }
    let step = s.maxNeighbourDistance * 0.9
    let drift = (0..<6).map { item("d\($0)", time: Double($0), at: Float($0) * step) }
    let groups = BurstGrouper.groups(for: drift)
    // Each step is within the neighbour limit, but frame 2 is already past
    // the anchor limit from frame 0, so the chain breaks into pairs.
    try check(
        groups.count == 3 && groups.allSatisfy { $0.members.count == 2 },
        "a slow drift grouped as \(groups.map(\.members.count))"
    )
    let edge = [item("e1", time: 0, at: 0), item("e2", time: s.maxGap, at: s.maxNeighbourDistance)]
    try check(BurstGrouper.groups(for: edge).count == 1, "limits are not inclusive")
    let past = [item("f1", time: 0, at: 0), item("f2", time: s.maxGap + 0.1, at: 0)]
    try check(BurstGrouper.groups(for: past).isEmpty, "a gap past the limit joined")
    try check(BurstGrouper.groups(for: [item("g", time: 0, at: 0)]).isEmpty, "a lone photo made a group")
}

/// A second visit computes nothing; an edited file is recomputed alone; a
/// cache for another folder is not mixed in; a damaged cache file is ignored.
public func verifyBurstCache() async throws {
    let folder = try scratchFolder()
    let cacheDir = try scratchFolder()
    defer {
        try? FileManager.default.removeItem(at: folder)
        try? FileManager.default.removeItem(at: cacheDir)
    }
    var urls: [URL] = []
    for i in 0..<5 {
        let url = folder.appendingPathComponent("p\(i).jpg")
        try Data("photo \(i)".utf8).write(to: url)
        urls.append(url)
    }
    let counter = CallCounter()
    let extractor: BurstAnalyzer.Extractor = { url in
        counter.record(url)
        return PhotoSignature(captureTime: 1, featurePrint: [1, 2, 3], sharpness: 7)
    }
    let cache = try BurstCache(folder: folder, directory: cacheDir)

    let first = await BurstAnalyzer.analyze(urls: urls, cache: cache, extractor: extractor)
    try check(first.count == 5 && counter.count == 5, "cold run computed \(counter.count)")

    counter.reset()
    let second = await BurstAnalyzer.analyze(urls: urls, cache: cache, extractor: extractor)
    try check(second == first && counter.count == 0, "warm run recomputed \(counter.count)")

    // Same file contents but a new modification date invalidates that entry only.
    counter.reset()
    let touched = urls[2]
    try FileManager.default.setAttributes(
        [.modificationDate: Date(timeIntervalSinceNow: 3600)], ofItemAtPath: touched.path
    )
    let third = await BurstAnalyzer.analyze(urls: urls, cache: cache, extractor: extractor)
    try check(counter.urls == [touched], "recomputed \(counter.urls.map(\.lastPathComponent))")
    try check(third[touched]?.stamp != first[touched]?.stamp, "stamp did not change")

    // A different size invalidates too.
    counter.reset()
    try Data("a longer replacement".utf8).write(to: urls[0])
    _ = await BurstAnalyzer.analyze(urls: urls, cache: cache, extractor: extractor)
    try check(counter.urls == [urls[0]], "size change recomputed \(counter.urls.map(\.lastPathComponent))")

    // In-memory knowledge is reused without the disk.
    counter.reset()
    _ = await BurstAnalyzer.analyze(urls: urls, known: third, cache: nil, extractor: extractor)
    try check(counter.urls == [urls[0]], "known entries were not reused")

    // A damaged cache file is ignored, not trusted and not fatal.
    try Data("not a plist".utf8).write(to: cache.fileURL)
    counter.reset()
    let again = await BurstAnalyzer.analyze(urls: urls, cache: cache, extractor: extractor)
    try check(again.count == 5 && counter.count == 5, "damaged cache computed \(counter.count)")

    // Another folder has its own file.
    let other = try BurstCache(folder: folder.appendingPathComponent("sub"), directory: cacheDir)
    try check(other.fileURL != cache.fileURL, "two folders share a cache file")

    // Cancelling keeps what the disk already knew.
    let task = Task { await BurstAnalyzer.analyze(urls: urls, cache: cache, extractor: extractor) }
    task.cancel()
    _ = await task.value
    try check(cache.load().count == 5, "a cancelled run dropped cached entries")
}

private final class CallCounter: @unchecked Sendable {
    private let lock = NSLock()
    private var calls: [URL] = []
    func record(_ url: URL) { lock.lock(); calls.append(url); lock.unlock() }
    func reset() { lock.lock(); calls = []; lock.unlock() }
    var count: Int { lock.lock(); defer { lock.unlock() }; return calls.count }
    var urls: [URL] { lock.lock(); defer { lock.unlock() }; return calls }
}

/// Keep sets exactly one pick and rejects the others, leaves labels and other
/// photos alone, is idempotent, and one undo restores every flag.
@MainActor
public func verifyBurstKeepActions() async throws {
    let dir = URL(fileURLWithPath: "/burst-keep")
    let urls = (0..<4).map { dir.appendingPathComponent("p\($0).jpg") }
    let outsider = dir.appendingPathComponent("outsider.jpg")
    let keymap = VimKeymap()
    // Start mixed: p0 rejected, p1 picked, p2 untouched, p3 picked and
    // labelled; the outsider is picked and must stay so.
    keymap.rejects = [urls[0]]
    keymap.picks = [urls[1], urls[3], outsider]
    keymap.colorLabels = [urls[3]: 4]

    let snapshot = keymap.keep(urls[2], rejectingRestOf: urls)
    try check(keymap.picks == [urls[2], outsider], "picks \(keymap.picks.map(\.lastPathComponent).sorted())")
    try check(keymap.rejects == [urls[0], urls[1], urls[3]], "rejects \(keymap.rejects.map(\.lastPathComponent).sorted())")
    try check(keymap.colorLabel(for: urls[3]) == 4, "a label changed")

    // Doing it again changes nothing: the keys toggle, the keep does not.
    keymap.keep(urls[2], rejectingRestOf: urls)
    try check(keymap.picks == [urls[2], outsider] && keymap.rejects == [urls[0], urls[1], urls[3]], "keep is not idempotent")

    keymap.restore(snapshot)
    try check(keymap.picks == [urls[1], urls[3], outsider], "undo picks \(keymap.picks.map(\.lastPathComponent).sorted())")
    try check(keymap.rejects == [urls[0]], "undo rejects \(keymap.rejects.map(\.lastPathComponent).sorted())")
    try check(keymap.colorLabel(for: urls[3]) == 4, "undo changed a label")

    // The state a keep leaves is what a save and load bring back: it was
    // made by the same actions every other cull uses.
    try check(keymap.hasUnpersistedChanges, "keep and undo left no change to persist")
}
